import { computeModesPerStep, computeReachableSteps, nextRefsForMode, renderFlow, renderMarkdown, TARGETS, } from "bitfab-flow";
import { describe, expect, it } from "vitest";
import { setupFlow } from "./setup.js";
const TARGET_NAMES = ["claude", "cursor", "codex"];
function findStep(phaseId, stepId) {
    const phase = setupFlow.phases.find((p) => p.id === phaseId);
    if (phase === undefined) {
        throw new Error(`phase "${phaseId}" not found`);
    }
    const step = phase.steps.find((s) => s.id === stepId);
    if (step === undefined) {
        throw new Error(`step "${phaseId}/${stepId}" not found`);
    }
    return step;
}
describe("setupFlow schema invariants", () => {
    it("declares all twelve invocation modes with `wizard` as defaultMode", () => {
        expect(Object.keys(setupFlow.entries).sort()).toEqual([
            "analyze-repo",
            "db-snapshot",
            "explain",
            "inspect",
            "instrument",
            "login",
            "modify",
            "replay",
            "session-logs",
            "switch-org",
            "templates",
            "view",
            "wizard",
        ]);
        expect(setupFlow.defaultMode).toBe("wizard");
    });
    it("analyze-repo mode enters at preflight and is a self-contained non-interactive phase", () => {
        expect(setupFlow.entries["analyze-repo"]).toBe("analyze-repo/preflight");
        const phase = setupFlow.phases.find((p) => p.id === "analyze-repo");
        expect(phase).toBeDefined();
        const analyzePhase = phase;
        // Non-interactive: no step in the phase may call AskUserQuestion, and none
        // may open Studio via the blocking openTracePlan CLI.
        for (const step of analyzePhase.steps) {
            expect(step.toolCalls ?? []).not.toContain("ask");
            expect(step.commandCalls ?? []).not.toContain("openTracePlan");
        }
        // preflight gates on auth via get_bitfab_api_key.
        expect(findStep("analyze-repo", "preflight").toolCalls).toContain("apiKey");
        // build-and-upload uploads plans (save_trace_plan) but never opens the
        // browser confirmation UI.
        const build = findStep("analyze-repo", "build-and-upload");
        expect(build.toolCalls).toContain("saveTracePlan");
        // The body must explicitly instruct skipping the blocking browser
        // confirmation (the phase-wide loop above already asserts openTracePlan is
        // not in commandCalls).
        expect(build.body).toMatch(/do NOT run `openTracePlan/);
        // report converges on the shared cleanup step like every other mode.
        const report = findStep("analyze-repo", "report");
        if (report.kind === "action") {
            expect(report.next).toBe("cleanup/close-studio");
        }
    });
    it("analyze-repo refreshes an existing draft for a key instead of drafting a rival", () => {
        const build = findStep("analyze-repo", "build-and-upload");
        expect(build.toolCalls).toContain("listTracePlans");
        // Per key, not one org-wide listing: that one is capped at 20 (50 max) and
        // unpaginated, so an older draft falls off the end and gets duplicated.
        expect(build.body).toMatch(/{ traceFunctionKey: "<that candidate's key>", status: "awaiting" }/);
        expect(build.body).toMatch(/never once for the whole org/);
        expect(build.body).toMatch(/take the FIRST of these three moves that matches/);
        expect(build.body).toMatch(/{ planId, tree, capturedNodeIds }/);
        // A second run over the same repo used to leave two drafts per key, both of
        // them offered in the reuse menu.
        expect(build.body).toMatch(/does not replace the first, it competes/);
        // A confirmed plan records what the code captures now, so it is never the
        // thing a re-scan overwrites.
        expect(build.body).toMatch(/counts as no awaiting plan/);
        // Nor is a plan from a live interactive cycle: the user may have it open in
        // Studio, so the batch neither clobbers it nor drafts a rival beside it.
        expect(build.body).toMatch(/skip the candidate entirely/);
        expect(build.body).toMatch(/open in Studio right now/);
        expect(build.body).toMatch(/Touch nothing, not the interactive plan/);
    });
    it("retires duplicate awaiting drafts for a key instead of leaving strays", () => {
        // A key can already carry duplicates from runs that predate the one-plan
        // rule; refreshing the newest and leaving the rest reusable still shows the
        // user two plans for one workflow.
        const build = findStep("analyze-repo", "build-and-upload");
        expect(build.toolCalls).toContain("cancelTracePlan");
        expect(build.body).toMatch(/retire the older `analyze_repo` siblings/);
        // Ordered, not a menu: the probe returns every awaiting plan for the key,
        // so an unordered read would let the refresh cancel a live interactive plan.
        expect(build.body).toMatch(/take the FIRST of these three moves that matches/);
        expect(build.body).toMatch(/Retire only `analyze_repo` drafts/);
        const instrument = findStep("instrument", "build-trace-plan");
        expect(instrument.toolCalls).toContain("cancelTracePlan");
        if (typeof instrument.body !== "string") {
            throw new Error("expected string body");
        }
        expect(instrument.body).toMatch(/retire the older ones/);
        const modify = findStep("modify", "reconstruct-current-plan");
        expect(modify.toolCalls).toContain("cancelTracePlan");
        expect(modify.body).toMatch(/retire the ones you did not take/);
    });
    it("analyze-repo detects existing instrumentation and uploads a per-node diff for already-traced workflows", () => {
        // scan gathers the existing-instrumentation map (greps for SDK usage).
        const scan = findStep("analyze-repo", "scan");
        expect(scan.body).toMatch(/already instrumented/i);
        expect(scan.body).toContain("withSpan");
        expect(scan.body).toContain("alreadyTraced");
        // build-and-upload sets the diff fields per node and reuses the existing key.
        const build = findStep("analyze-repo", "build-and-upload");
        expect(build.body).toContain("alreadyTraced");
        expect(build.body).toContain("alreadyMocked");
        // The diff must be unambiguous: every node carries alreadyTraced on a diff
        // plan, and greenfield plans omit it entirely.
        expect(build.body).toMatch(/every.*node/i);
        expect(build.body).toMatch(/existing.*traceFunctionKey/i);
        expect(build.body).toMatch(/[Oo]mit both fields entirely on greenfield/);
        // report surfaces the delta (new spans vs dropped spans) per candidate.
        const report = findStep("analyze-repo", "report");
        expect(report.body).toMatch(/new span/i);
        expect(report.body).toMatch(/drop/i);
    });
    it("the claude analyze-repo sub-skill is NOT granted AskUserQuestion (non-interactivity is enforced, not just instructed)", () => {
        const files = renderFlow(setupFlow, TARGETS.claude);
        const subSkill = files.find((f) => f.slug === "analyze-repo");
        expect(subSkill).toBeDefined();
        // The allowed-tools frontmatter line must not grant AskUserQuestion, so the
        // Claude permission layer denies any attempt to prompt the user.
        const allowedToolsLine = subSkill.content
            .split("\n")
            .find((line) => line.startsWith("allowed-tools:"));
        expect(allowedToolsLine).toBeDefined();
        expect(allowedToolsLine).not.toContain("AskUserQuestion");
        // Sanity: it still grants the tools the phase actually needs.
        expect(allowedToolsLine).toContain("save_trace_plan");
    });
    it("the analyze-repo phase is reachable only in `analyze-repo` mode", () => {
        for (const targetName of TARGET_NAMES) {
            const modesPerStep = computeModesPerStep(setupFlow, targetName);
            for (const stepId of [
                "analyze-repo/preflight",
                "analyze-repo/scan",
                "analyze-repo/select",
                "analyze-repo/build-and-upload",
                "analyze-repo/report",
            ]) {
                expect([...(modesPerStep.get(stepId) ?? [])]).toEqual(["analyze-repo"]);
            }
        }
    });
    it("the approach phase is reachable only in `wizard` mode for every target", () => {
        for (const targetName of TARGET_NAMES) {
            const modesPerStep = computeModesPerStep(setupFlow, targetName);
            for (const stepId of [
                "approach/choose-driver",
                "approach/whats-next",
                "approach/self-serve-handoff",
            ]) {
                const stepModes = modesPerStep.get(stepId);
                expect(stepModes, `step "${stepId}" unreachable`).toBeDefined();
                expect([...(stepModes ?? [])]).toEqual(["wizard"]);
            }
        }
    });
    it("wizard logs in first, then runs the shared explain, then asks who instruments", () => {
        expect(setupFlow.entries.wizard).toBe("login/status-check");
        const loginExit = findStep("login", "ask-session-log-consent");
        expect(loginExit.kind).toBe("action");
        if (loginExit.kind !== "action") {
            throw new Error("unreachable");
        }
        expect(loginExit.next).toEqual(expect.objectContaining({
            byMode: expect.objectContaining({
                wizard: "explain/overview",
                instrument: "instrument/detect-language",
            }),
        }));
        const explain = findStep("explain", "overview");
        expect(explain.kind).toBe("action");
        if (explain.kind !== "action") {
            throw new Error("unreachable");
        }
        expect(explain.next).toEqual(expect.objectContaining({
            byMode: expect.objectContaining({
                wizard: "approach/choose-driver",
                explain: "cleanup/close-studio",
            }),
        }));
        const step = findStep("approach", "choose-driver");
        expect(step.kind).toBe("branch");
        if (step.kind !== "branch") {
            throw new Error("unreachable");
        }
        const guided = step.branches.find((b) => b.option?.letter === "A");
        expect(guided?.recommended).toBe(true);
        expect(guided?.next).toBe("approach/whats-next");
        const self = step.branches.find((b) => b.option?.letter === "B");
        expect(self?.recommended).toBeUndefined();
        expect(self?.next).toBe("approach/self-serve-handoff");
    });
    it("self-serve handoff points at the MCP tool without calling it or printing a key", () => {
        const step = findStep("approach", "self-serve-handoff");
        expect(step.kind).toBe("action");
        if (step.kind !== "action") {
            throw new Error("unreachable");
        }
        expect(step.toolCalls ?? []).toEqual([]);
        expect(step.commandCalls ?? []).toEqual([]);
        expect(step.next).toBe("cleanup/close-studio");
        const body = String(step.body);
        expect(body).toContain("https://docs.bitfab.ai");
        expect(body).toContain("`get_bitfab_api_key` tool");
        expect(body).toContain("Do **not** call it yourself, and never print a key.");
        expect(body).not.toContain("credentials.json");
        expect(body).not.toContain("{{tool:");
        // Monoliths keep rendering Instrument below this step and mark it valid for
        // `wizard`, so "stop" has to name the sections it must not fall into.
        expect(body).toContain("{{skill-ref:cleanup}}");
        expect(body).toContain("do **not** read on into the sections that follow");
        const approach = renderFlow(setupFlow, TARGETS.claude).find((f) => f.content.includes("name: setup-approach"));
        const allowed = approach?.content.match(/^allowed-tools: (.*)$/m)?.[1];
        expect(allowed).toBeDefined();
        expect(allowed).not.toContain("get_bitfab_api_key");
    });
    it("approach phase is the first step of its own sub-skill (split-chain entry)", () => {
        const phase = setupFlow.phases.find((p) => p.id === "approach");
        expect(phase?.steps[0]?.id).toBe("choose-driver");
    });
    it("login phase gates `wizard`, `login`, and `instrument` modes", () => {
        for (const targetName of TARGET_NAMES) {
            const modesPerStep = computeModesPerStep(setupFlow, targetName);
            const loginStartModes = modesPerStep.get("login/status-check");
            expect(loginStartModes).toBeDefined();
            expect([...(loginStartModes ?? [])].sort()).toEqual([
                "instrument",
                "login",
                "wizard",
            ]);
        }
    });
    it("login/run-login failure path routes to cleanup", () => {
        const step = findStep("login", "run-login");
        expect(step.kind).toBe("branch");
        if (step.kind !== "branch") {
            throw new Error("unreachable");
        }
        const failureBranch = step.branches.find((b) => b.when === "login fails, errors, or times out" &&
            b.next === "cleanup/close-studio");
        expect(failureBranch).toBeDefined();
    });
    it.each(TARGET_NAMES)("tells %s to surface fresh Studio URLs from window-open-requested events", (targetName) => {
        const output = renderMarkdown(setupFlow, TARGETS[targetName]);
        expect(output).toContain('{"event":"window-open-requested","url":"..."}');
        expect(output).toContain("Opening Studio: <url>");
        expect(output).toContain("Click it if a window doesn't appear");
    });
    it.each(TARGET_NAMES)("tells %s to describe an unreachable Studio as a backgrounded window, not a session pointer", (targetName) => {
        const output = renderMarkdown(setupFlow, TARGETS[targetName]);
        expect(output).toContain("Describe this to the user in terms of their browser window, never the plumbing.");
        expect(output).toContain("Your browser may have backgrounded it.");
        expect(output).not.toContain("to drop the stale pointer");
        expect(output).not.toContain("force-clear a stale session");
    });
    it("instrument/search-existing 'Modify' option cross-phases to modify", () => {
        const step = findStep("instrument", "search-existing");
        expect(step.kind).toBe("branch");
        if (step.kind !== "branch") {
            throw new Error("unreachable");
        }
        const modifyBranch = step.branches.find((b) => b.option?.label === "Modify an existing trace setup");
        expect(modifyBranch).toBeDefined();
        expect(modifyBranch?.next).toBe("modify/gather-existing");
    });
    it("choose-discovery offers analyze-repo draft reuse as the first, recommended option", () => {
        const step = findStep("instrument", "choose-discovery");
        expect(step.toolCalls).toContain("listTracePlans");
        expect(step.kind).toBe("branch");
        if (step.kind !== "branch") {
            throw new Error("unreachable");
        }
        const reuse = step.branches.find((b) => b.option?.letter === "A");
        expect(reuse?.option?.label).toMatch(/[Rr]euse an analyze-repo draft/);
        expect(reuse?.recommended).toBe(true);
        expect(reuse?.next).toBe("instrument/reconcile-existing-plan");
        expect(step.branches.find((b) => b.option?.letter === "B")?.next).toBe("instrument/identify-workflows");
        expect(step.branches.find((b) => b.option?.letter === "C")?.next).toBe("instrument/read-target");
        expect(step.body).toMatch(/only present when.*returned at least one draft/i);
        expect(step.body).toMatch(/analyze_repo/);
    });
    it("reconcile-existing-plan reconciles a draft against current code and forks", () => {
        const step = findStep("instrument", "reconcile-existing-plan");
        expect(step.kind).toBe("branch");
        if (step.kind !== "branch") {
            throw new Error("unreachable");
        }
        for (const tool of [
            "getTracePlan",
            "saveTracePlan",
            "cancelTracePlan",
            "listFunctions",
            "read",
            "grep",
        ]) {
            expect(step.toolCalls).toContain(tool);
        }
        expect(step.body).toMatch(/before you present or open the plan/i);
        expect(step.body).toMatch(/duplicate the trace|second root span/);
        expect(step.body).toMatch(/setup modify/);
        expect(step.body).toMatch(/[Ss]tale/);
        const greenfield = step.branches.find((b) => b.option?.letter === "A");
        expect(greenfield?.recommended).toBe(true);
        expect(greenfield?.next).toBe("instrument/build-trace-plan");
        // A moot draft is retired rather than skipped: skipping left it `awaiting`,
        // so it came back in every later reuse probe.
        expect(step.branches.find((b) => b.option?.letter === "B")?.next).toBe("instrument/reconcile-existing-plan");
        expect(step.branches.find((b) => b.option?.letter === "D")?.next).toBe("instrument/reconcile-existing-plan");
        expect(step.body).toMatch(/{{tool:cancelTracePlan}}/);
        // A stale-but-alive draft is refreshed onto the same plan id, never dropped
        // in favour of a competing second plan for the key.
        expect(step.branches.find((b) => b.option?.letter === "C")?.next).toBe("instrument/build-trace-plan");
        expect(step.body).toMatch(/{ planId, tree, capturedNodeIds }/);
        expect(step.body).toMatch(/never create a competing plan/i);
    });
    it("build-trace-plan carries a reuse entry that skips build for existing plans", () => {
        const step = findStep("instrument", "build-trace-plan");
        if (typeof step.body !== "string") {
            throw new Error("expected string body");
        }
        expect(step.body).toMatch(/Reuse entry/i);
        expect(step.body).toMatch(/instrument\/reconcile-existing-plan/);
        expect(step.body).toMatch(/do NOT create a plan here/i);
    });
    it("build-trace-plan revises the saved plan in place instead of posting a rival", () => {
        const step = findStep("instrument", "build-trace-plan");
        if (typeof step.body !== "string") {
            throw new Error("expected string body");
        }
        expect(step.body).toMatch(/revise the plan you already saved/i);
        expect(step.body).toMatch(/Never call {{tool:saveTracePlan}} without/);
        // A typed change mid-review updates the open plan, which re-renders itself,
        // so Studio no longer gets torn down and reopened for every revision.
        expect(step.body).toMatch(/leave Studio open and leave the background/i);
        expect(step.body).toMatch(/Never create a second plan here/);
    });
    it("instrument/next-workflow re-probes drafts and offers saved-plan reuse each loop", () => {
        const step = findStep("instrument", "next-workflow");
        expect(step.kind).toBe("branch");
        if (step.kind !== "branch") {
            throw new Error("unreachable");
        }
        expect(step.toolCalls).toContain("listTracePlans");
        expect(step.body).toMatch(/EVERY pass/);
        expect(step.body).toMatch(/analyze_repo/);
        const aBranch = step.branches.find((b) => b.option?.letter === "A");
        expect(aBranch?.option?.label).toMatch(/saved trace plan/i);
        expect(aBranch?.recommended).toBe(true);
        expect(aBranch?.next).toBe("instrument/reconcile-existing-plan");
        expect(step.branches.find((b) => b.option?.letter === "B")?.next).toBe("instrument/identify-workflows");
        expect(step.branches.find((b) => b.option?.letter === "C")?.next).toBe("instrument/read-target");
        expect(step.branches.find((b) => b.option?.letter === "D")?.next).toBe("cleanup/close-studio");
    });
    it("'What's about to happen next' fires right after the walk-me-through choice", () => {
        const choose = findStep("approach", "choose-driver");
        if (choose.kind !== "branch") {
            throw new Error("unreachable");
        }
        // Option A lands on the expectations step, not straight in the instrument
        // phase: the existing-SDK path shows a detection report and its own menu
        // before the workflow question, so anything deeper renders too late.
        const guided = choose.branches.find((b) => b.option?.letter === "A");
        expect(guided?.next).toBe("approach/whats-next");
        const step = findStep("approach", "whats-next");
        expect(step.kind).toBe("action");
        if (step.kind !== "action") {
            throw new Error("unreachable");
        }
        expect(step.next).toBe("instrument/detect-language");
        const body = String(step.body);
        expect(body).toContain("**What's about to happen next**");
        expect(body).toContain("write a `replay` script using the Bitfab SDK");
        expect(body).toContain("10 - 17 minutes");
        // The phase is wizard-only, so this needs no mode gate.
        expect(body).not.toContain("{{#mode:");
        // Monoliths render no routing arrow for an action step's `next`, so a
        // sequential reader would fall into the self-serve handoff that follows.
        // The prose has to hand off to Instrument explicitly.
        expect(body).toContain("{{skill-ref:instrument}}");
        expect(body).toContain("do **not** continue into the self-serve handoff");
        for (const stepId of ["detect-language", "choose-discovery"]) {
            expect(String(findStep("instrument", stepId).body)).not.toContain("What's about to happen next");
        }
    });
    it("the primitives explainer teaches withSpan/replay and the five replay modes", () => {
        const explainer = String(findStep("explain", "overview").body);
        expect(explainer).toContain("**Purpose**");
        expect(explainer).toContain("**How to instrument**");
        expect(explainer).toContain("`withSpan(...)`");
        expect(explainer).toContain("`replay(...)`");
        for (const mode of [
            "1. Execute as normal",
            "2. Pass in inputs from the recorded trace",
            "3. Pass in modified inputs from the recorded trace",
            "4. Skip execution and return outputs from the recorded trace",
            "5. Skip execution and return modified outputs from the recorded trace",
        ]) {
            expect(explainer).toContain(mode);
        }
    });
    it("the mode menu sits in an `explain`-only section, gated by the renderer", () => {
        const body = String(findStep("explain", "overview").body);
        expect(body).toContain("{{#mode:explain}}");
        expect(body).toContain("{{/mode:explain}}");
        expect(body).toContain("{{^mode:explain}}");
        expect(body).toContain("What you can run");
        // The explain unit serves both `explain` and `wizard`, so neither branch
        // can be stripped at compile time: both must survive as rendered gates.
        for (const targetName of TARGET_NAMES) {
            const rendered = renderMarkdown(setupFlow, TARGETS[targetName]);
            expect(rendered).not.toContain("{{#mode:");
            expect(rendered).not.toContain("{{^mode:");
            expect(rendered).not.toContain("{{/mode:");
            expect(rendered).toContain("**Only when the mode is `explain`:**");
            expect(rendered).toContain("**Unless the mode is `explain`:**");
        }
    });
    it("replay/safety-net falls through to cleanup when every function is invocable", () => {
        const step = findStep("replay", "safety-net");
        expect(step.kind).toBe("branch");
        if (step.kind !== "branch") {
            throw new Error("unreachable");
        }
        // The A/B/C options only fire when a function is un-invocable; the common
        // "everything callable" path must be an explicit `when` arm to cleanup, or
        // the split-chain dead-ends without running closeStudio.js.
        const fallThrough = step.branches.find((b) => b.option === undefined && b.when !== undefined);
        expect(fallThrough).toBeDefined();
        expect(fallThrough?.next).toBe("cleanup/close-studio");
    });
    it("switch-org/perform-switch routes not-member/error to cleanup, not a prose stop", () => {
        const step = findStep("switch-org", "perform-switch");
        expect(step.kind).toBe("branch");
        if (step.kind !== "branch") {
            throw new Error("unreachable");
        }
        const failureArm = step.branches.find((b) => b.when?.includes("not-member"));
        expect(failureArm).toBeDefined();
        expect(failureArm?.next).toBe("cleanup/close-studio");
        const successArm = step.branches.find((b) => b.when?.includes("switched"));
        expect(successArm?.next).toBe("switch-org/update-local-env");
    });
    it("templates/check-traces routes an existing trace through preview-mode, never straight to open-preview", () => {
        const step = findStep("templates", "check-traces");
        expect(step.kind).toBe("branch");
        if (step.kind !== "branch") {
            throw new Error("unreachable");
        }
        const traceExists = step.branches.find((b) => b.when?.includes("trace exists"));
        expect(traceExists?.next).toBe("templates/preview-mode");
    });
    it("templates/preview-mode lets the user edit inline (skip preview) or open the live preview", () => {
        const step = findStep("templates", "preview-mode");
        expect(step.kind).toBe("branch");
        if (step.kind !== "branch") {
            throw new Error("unreachable");
        }
        // Inline arm skips the preview entirely and drops straight into the edit loop,
        // so a user already viewing a trace is never yanked onto the preview page.
        const inlineArm = step.branches.find((b) => b.when?.includes("inline"));
        expect(inlineArm?.next).toBe("templates/edit-loop");
        // Preview arm opens the chromeless preview first, then enters the same edit loop.
        const previewArm = step.branches.find((b) => b.when?.includes("live preview"));
        expect(previewArm?.next).toBe("templates/open-preview");
    });
    it("replay phase is reachable only through explicit replay mode", () => {
        for (const targetName of TARGET_NAMES) {
            const modesPerStep = computeModesPerStep(setupFlow, targetName);
            const replayStartModes = modesPerStep.get("replay/gather-keys");
            expect(replayStartModes).toBeDefined();
            expect([...(replayStartModes ?? [])].sort()).toEqual(["replay"]);
        }
    });
    it("modify phase is reachable in `wizard`, `instrument`, and `modify` modes", () => {
        for (const targetName of TARGET_NAMES) {
            const modesPerStep = computeModesPerStep(setupFlow, targetName);
            const modifyStartModes = modesPerStep.get("modify/gather-existing");
            expect(modifyStartModes).toBeDefined();
            expect([...(modifyStartModes ?? [])].sort()).toEqual([
                "instrument",
                "modify",
                "wizard",
            ]);
        }
    });
    it("the explain phase is shared by `explain` and `wizard`, and nothing else", () => {
        for (const targetName of TARGET_NAMES) {
            const modesPerStep = computeModesPerStep(setupFlow, targetName);
            const explainModes = modesPerStep.get("explain/overview");
            expect(explainModes).toBeDefined();
            expect([...(explainModes ?? [])].sort()).toEqual(["explain", "wizard"]);
        }
    });
    it("inspect phase is reachable only in `inspect` mode", () => {
        for (const targetName of TARGET_NAMES) {
            const modesPerStep = computeModesPerStep(setupFlow, targetName);
            const inspectModes = modesPerStep.get("inspect/status-check");
            expect(inspectModes).toBeDefined();
            expect([...(inspectModes ?? [])].sort()).toEqual(["inspect"]);
        }
    });
    it("db-snapshot phase is reachable only in `db-snapshot` mode", () => {
        for (const targetName of TARGET_NAMES) {
            const modesPerStep = computeModesPerStep(setupFlow, targetName);
            const startModes = modesPerStep.get("db-snapshot/preflight");
            expect(startModes).toBeDefined();
            expect([...(startModes ?? [])].sort()).toEqual(["db-snapshot"]);
        }
    });
    it("registers the get_database_connection_status MCP tool and polls it in await-connection", () => {
        expect(setupFlow.tools.dbConnectionStatus).toEqual({
            kind: "mcp",
            name: "get_database_connection_status",
        });
        const connect = findStep("db-snapshot", "connect-db");
        expect(connect.toolCalls).toContain("dbConnectionStatus");
        const await_ = findStep("db-snapshot", "await-connection");
        expect(await_.toolCalls).toContain("dbConnectionStatus");
    });
    it("db-snapshot/await-connection loops on `checking` and exits to wire-replay on `connected`", () => {
        const step = findStep("db-snapshot", "await-connection");
        expect(step.kind).toBe("branch");
        if (step.kind !== "branch") {
            throw new Error("unreachable");
        }
        const connected = step.branches.find((b) => b.when === "status is connected");
        expect(connected?.next).toBe("db-snapshot/wire-replay");
        const checking = step.branches.find((b) => b.when === "status is checking");
        expect(checking?.next).toBe("db-snapshot/await-connection");
    });
    it("db-snapshot wires the replay branch per language and has no capture-config step (capture is always-on)", () => {
        const phase = setupFlow.phases.find((p) => p.id === "db-snapshot");
        expect(phase?.steps.some((s) => s.id === "enable-snapshot")).toBe(false);
        expect(phase?.intro).toContain("Eligible root traces");
        expect(phase?.intro).toContain("subject to replication lag");
        expect(phase?.intro).not.toContain("so any trace can later be replayed");
        const wire = findStep("db-snapshot", "wire-replay");
        expect(wire.body).toMatch(/getCurrentReplayBranch\(\)/); // TypeScript
        expect(wire.body).toMatch(/get_current_replay_branch\(\)/); // Python
        expect(wire.body).toMatch(/Bitfab\.current_replay_branch/); // Ruby
        // The boolean is the switch, so each snippet must show it rather than an
        // empty options object: settings are only for tuning the branch.
        expect(wire.body).toMatch(/dbBranch: true/); // TypeScript
        expect(wire.body).toMatch(/db_branch=True/); // Python
        expect(wire.body).toMatch(/db_branch: true/); // Ruby
        const smoke = findStep("db-snapshot", "smoke-test");
        expect(smoke.kind).toBe("action");
        if (smoke.kind !== "action") {
            throw new Error("unreachable");
        }
        expect(smoke.toolCalls).toContain("searchTraces");
        expect(smoke.body).toContain("Mandatory replay-safety check");
        expect(smoke.body).toContain('traceFunctionKey: "<key>"');
        expect(smoke.body).toContain("hasDbSnapshot: true");
        expect(smoke.body).toContain("--trace-ids <fresh-trace-id>");
        expect(smoke.body).toContain("Mocking, not the app environment");
        expect(smoke.body).toContain("does not return trace inputs");
        expect(smoke.body).not.toContain("whose shown input matches");
        expect(smoke.body).not.toContain("scripts/replay.ts <pipeline> --limit 1");
        expect(smoke.body).toMatch(/getCurrentReplayBranch\(\)/);
        expect(smoke.body).toMatch(/get_current_replay_branch\(\)/);
        expect(smoke.body).toMatch(/Bitfab\.current_replay_branch/);
        expect(smoke.body).toContain("no separate replay-environment active flag");
        expect(smoke.body).not.toContain("environment's active flag");
        expect(smoke.next).toBe("cleanup/close-studio");
    });
    it("modify/reconstruct-current-plan reconciles a prior plan against current code", () => {
        const step = findStep("modify", "reconstruct-current-plan");
        expect(step.toolCalls).toContain("getTracePlan");
        expect(step.toolCalls).toContain("read");
        expect(step.toolCalls).toContain("grep");
        expect(step.body).toMatch(/traceFunctionKey/);
        expect(step.body).toMatch(/historical user intent/);
        expect(step.body).toMatch(/never proof of what the code captures now/);
        expect(step.body).toMatch(/MUST reread and reconcile current instrumentation/);
        expect(step.body).toMatch(/mandatory in both outcomes/);
        expect(step.body).toMatch(/Present in code, absent from the stored plan/);
        expect(step.body).toMatch(/no longer instrumented in code/);
        expect(step.body).toMatch(/Moved or renamed/);
        expect(step.body).toMatch(/Root changed/);
        expect(step.body).toMatch(/supports changing the root/);
        expect(step.body).toMatch(/never retain an obsolete root/);
        expect(step.body).toMatch(/including each manual or auto span discovered/);
        expect(step.body).toMatch(/may copy the `before` tree unchanged/);
        expect(step.body).toMatch(/analysis completeness at the same boundary/);
        expect(step.body).toMatch(/never persist an unclassified captured span/);
        expect(step.body).toMatch(/never omit a current manual\/auto span/);
        expect(step.body).not.toMatch(/do not need to re-read the instrumented files/i);
    });
    it("modify/reconstruct-current-plan looks for an unconfirmed plan before creating one", () => {
        const step = findStep("modify", "reconstruct-current-plan");
        expect(step.toolCalls).toContain("listTracePlans");
        // get_trace_plan by key answers only for confirmed plans, so the miss says
        // nothing about the analyze-repo draft (or unconfirmed plan) on that key.
        expect(step.body).toMatch(/only rules out a \*confirmed\* plan/);
        expect(step.body).toMatch(/{ traceFunctionKey: "<chosen key>", status: "awaiting" }/);
        expect(step.body).toMatch(/An awaiting plan came back/);
        expect(step.body).toMatch(/Nothing came back/);
    });
    it("modify/build-modified-plan requires surrounding callees as pure context, never callers above the root", () => {
        const step = findStep("modify", "build-modified-plan");
        expect(step.body).toMatch(/~10 callees below/);
        expect(step.body).toMatch(/~5 siblings per captured node BELOW the root/);
        expect(step.body).toMatch(/`pure`/);
        expect(step.body).not.toMatch(/callers above the root/);
        expect(step.body).toMatch(/MUST be a descendant of the root/);
        expect(step.body).toMatch(/Don't generate siblings for the root/);
    });
    it("modify/present-diff preserves the descendant-only context rule", () => {
        const step = findStep("modify", "present-diff");
        expect(step.body).toMatch(/~10 surrounding callees/);
        expect(step.body).toMatch(/~5 sibling callees/);
        expect(step.body).toMatch(/never include callers above the root/);
        expect(step.body).not.toMatch(/~10 surrounding callers/);
    });
    it("modify/present-diff routes a cancelled trace plan to the apply branch (leaving the plan page continues)", () => {
        const step = findStep("modify", "present-diff");
        expect(step.kind).toBe("branch");
        if (step.kind !== "branch") {
            throw new Error("unreachable");
        }
        expect(step.toolCalls).toContain("saveTracePlan");
        expect(step.toolCalls).toContain("getTracePlan");
        const proceed = step.branches.find((b) => b.option?.letter === "A");
        expect(proceed?.next).toBe("modify/apply-changes");
        const modifications = step.branches.find((b) => b.option?.letter === "C");
        expect(modifications?.option?.label).toBe("Modifications");
        expect(modifications?.next).toBe("modify/build-modified-plan");
        const abort = step.branches.find((b) => b.option?.letter === "D");
        expect(abort?.option?.label).toBe("Abort entirely");
        expect(abort?.next).toBe("cleanup/close-studio");
        expect(step.body).toMatch(/"event":"cancelled".*branch \*\*A\*\*/s);
        expect(step.body).not.toMatch(/"event":"cancelled".*branch \*\*C\*\*/s);
    });
    it("instrument/build-trace-plan passes traceFunctionKey to save_trace_plan", () => {
        const step = findStep("instrument", "build-trace-plan");
        expect(step.body).toMatch(/traceFunctionKey/);
        expect(step.body).toMatch(/~10 callees below/);
        expect(step.body).toMatch(/~5 siblings per captured node BELOW the root/);
        expect(step.body).not.toMatch(/callers above the root/);
        expect(step.body).toMatch(/MUST be a descendant of the root/);
        expect(step.body).toMatch(/Don't generate siblings for the root/);
    });
    it("trace-plan delivery renders inline ASCII first, then offers browser or continue", () => {
        // Instrument: renders the plan inline, asks Open trace plan vs Continue
        // instrumenting, and the continue path proceeds without a Studio round-trip.
        const build = findStep("instrument", "build-trace-plan");
        expect(build.body).toMatch(/[Rr]ender the trace plan inline as ASCII/);
        expect(build.body).toMatch(/Open trace plan/);
        expect(build.body).toMatch(/If they pick Continue instrumenting/);
        // Continue must persist the plan as confirmed (else view/modify can't find
        // it by key), so it calls confirmTracePlan, not just getTracePlan.
        expect(build.body).toMatch(/\{\{tool:confirmTracePlan\}\}/);
        expect(build.toolCalls ?? []).toContain("confirmTracePlan");
        // The old "delivered ONE way only / forbidden to render inline" invariant
        // must be gone, inline ASCII is now the default surface.
        expect(build.body).not.toMatch(/delivered ONE way only/);
        expect(build.body).not.toMatch(/is forbidden/);
        // Modify: same render-then-ask shape; Continue maps to the apply branch.
        const modify = findStep("modify", "present-diff");
        expect(modify.body).toMatch(/[Rr]ender the modified plan inline as ASCII/);
        expect(modify.body).toMatch(/Open trace plan/);
        // Substep 1 posts the plan without opening Studio (render + ask come after).
        expect(modify.body).not.toMatch(/Post the modified plan and open the UI/);
        // "Open trace plan" is an explicit AskUserQuestion branch, not prose-only.
        if (modify.kind === "branch") {
            const browserBranch = modify.branches.find((b) => b.option?.label === "Open trace plan");
            expect(browserBranch).toBeDefined();
            expect(browserBranch?.next).toBe("modify/apply-changes");
        }
        // Modify Continue also persists via confirmTracePlan.
        expect(modify.body).toMatch(/\{\{tool:confirmTracePlan\}\}/);
        expect(modify.toolCalls ?? []).toContain("confirmTracePlan");
        // View: renders inline, then offers the browser as an optional read-only look.
        const view = findStep("view", "open-in-ui");
        expect(view.body).toMatch(/[Rr]ender the trace plan inline as ASCII/);
        expect(view.body).toMatch(/View in browser/);
    });
    it("view/fetch-plan falls back to an unconfirmed plan before reporting none", () => {
        const step = findStep("view", "fetch-plan");
        expect(step.toolCalls).toContain("listTracePlans");
        expect(step.body).toMatch(/rules out a \*confirmed\* plan, not every plan/);
        expect(step.body).toMatch(/{ traceFunctionKey: "<chosen key>", status: "awaiting" }/);
        // The fallback view stays read-only; it must not turn into an edit path.
        expect(step.body).toMatch(/rendered inline only, never opened in Studio/);
    });
    it("view never opens an unconfirmed plan in Studio, whose Save would confirm it", () => {
        const step = findStep("view", "open-in-ui");
        if (typeof step.body !== "string") {
            throw new Error("expected string body");
        }
        // Studio renders a confirmed plan read-only, but an awaiting one keeps its
        // Save/Close buttons, so "just looking" could promote a draft to confirmed
        // with no instrumentation written to match it.
        expect(step.body).toMatch(/do NOT offer the browser/);
        expect(step.body).toMatch(/still shows its \*\*Save\*\* and \*\*Close\*\*/);
        expect(step.body).toMatch(/For a \*\*confirmed\*\* plan/);
    });
    it("instrument/build-trace-plan saves onto an existing unconfirmed plan for the key", () => {
        const step = findStep("instrument", "build-trace-plan");
        if (typeof step.body !== "string") {
            throw new Error("expected string body");
        }
        expect(step.toolCalls).toContain("listTracePlans");
        expect(step.body).toMatch(/First check whether this key already has a plan/);
        expect(step.body).toMatch(/Only create when the probe is empty/);
        // The create bullet must read as the probe's other branch, not as a step
        // that also runs after a refresh, or both fire and the key gets a rival.
        expect(step.body).toMatch(/\*\*Only when that probe came back empty\*\*/);
        expect(step.body).toMatch(/one decision, not two steps/);
        expect(step.body).toMatch(/must NOT also create one/);
        // A confirmed plan is not a refresh target: that is a Modify cycle.
        expect(step.body).toMatch(/leave it alone/);
    });
    it("instrument/build-trace-plan creates fresh only when the plan is cancelled", () => {
        const step = findStep("instrument", "build-trace-plan");
        if (typeof step.body !== "string") {
            throw new Error("expected string body");
        }
        // A cancelled plan cannot be updated, so it is the one exception to
        // revising in place. An expired one is revived by the save itself.
        expect(step.body).toMatch(/one exception to revising in place/);
        expect(step.body).toMatch(/again \*without\* `planId`/);
        expect(step.body).toMatch(/An expired plan needs no such handling/);
    });
    it("modify/present-diff leaves Studio open when the user types a change", () => {
        const step = findStep("modify", "present-diff");
        if (typeof step.body !== "string") {
            throw new Error("expected string body");
        }
        // Only the finishing branch tears Studio down now: a revision re-saves the
        // same plan id and the open page re-renders itself.
        expect(step.body).toMatch(/\*\*A typed change\*\* \(branch \*\*C\*\*\) does neither/);
        expect(step.body).toMatch(/re-renders itself when that update lands/);
    });
    it("leaving the Studio trace plan page always continues, never aborts", () => {
        const build = findStep("instrument", "build-trace-plan");
        // Close and Save are the only buttons the page offers, and neither is an
        // abort: a cancelled terminal event still confirms the plan and instruments.
        expect(build.body).toMatch(/\*\*Close\*\*/);
        expect(build.body).toMatch(/\*\*Save\*\*/);
        expect(build.body).toMatch(/"event":"cancelled".*Treat this as continue, not as an abort/s);
        expect(build.body).not.toMatch(/the trace setup was dropped/);
        // Saying "continue" in chat closes the plan by navigating Studio in
        // place; closeStudio would tear down the whole tab.
        expect(build.body).toMatch(/\{\{command:openStudio\}\} "\/studio"[\s\S]*never use `\{\{command:closeStudio\}\}`/);
        expect(build.commandCalls ?? []).toContain("openStudio");
    });
    it("lets a Studio decision win over a leftover answer to the continue question", () => {
        // The question stays on screen while Studio is open, so a user who clicks
        // Save and then clears it must not have their toggles overwritten by a
        // re-confirm with the agent's own recommended set.
        for (const step of [
            findStep("instrument", "build-trace-plan"),
            findStep("modify", "present-diff"),
        ]) {
            expect(step.body).toMatch(/stdout (BEFORE|before) acting on (the|their) answer/);
            // The pause is a yes/no confirm, not a fork; "wait" is what the open
            // question already does, so it is never one of the options.
            expect(step.body).toMatch(/single yes\/no question/);
            expect(step.body).toMatch(/Waiting is never an option/);
            // Studio is optional at every point: the terminal alone can finish the
            // flow, both from the question and from a later "continue" in chat.
            expect(step.body).toMatch(/must always be able to finish without touching Studio/);
            // A capture saved in Studio outranks the agent's recommendation even when
            // it lands after the stdout read, i.e. the confirm comes back rejected.
            expect(step.body).toMatch(/no longer awaiting/);
            expect(step.body).toMatch(/\{\{tool:getTracePlan\}\}/);
        }
        expect(findStep("instrument", "build-trace-plan").body).toMatch(/the code and the plan disagree/);
    });
    it("trace-plan steps require analysis on every node, including context", () => {
        const buildTracePlan = findStep("instrument", "build-trace-plan");
        const buildModifiedPlan = findStep("modify", "build-modified-plan");
        const presentDiff = findStep("modify", "present-diff");
        expect(buildTracePlan.body).toMatch(/Every node in the `TracePlanTree`/);
        expect(buildTracePlan.body).toMatch(/including uncaptured surrounding context nodes/);
        expect(buildTracePlan.body).toMatch(/mockable `external_read` and `side_effect` nodes serve their recorded output by default/);
        expect(buildTracePlan.body).toMatch(/server defaults it to `true` for mockable `external_read` and `side_effect` nodes/);
        expect(buildTracePlan.body).toMatch(/`false` for `model_call` and `pure` nodes/);
        expect(buildTracePlan.body).toMatch(/smallest span that actually crosses/);
        expect(buildTracePlan.body).toMatch(/broad external parents with live descendants/);
        expect(buildTracePlan.body).not.toMatch(/uncaptured context nodes omit it/);
        expect(buildTracePlan.body).not.toMatch(/Omit `analysis`/);
        expect(buildTracePlan.body).not.toMatch(/replay re-runs every span by default/);
        expect(buildModifiedPlan.body).toMatch(/Every node in the modified `TracePlanTree`/);
        expect(buildModifiedPlan.body).toMatch(/Mockable `external_read` and `side_effect` nodes default to mocked replay/);
        expect(buildModifiedPlan.body).toMatch(/smallest external boundary/);
        expect(buildModifiedPlan.body).toMatch(/broad external parents with live descendants/);
        expect(buildModifiedPlan.body).toMatch(/older prior plans that lack `analysis`/);
        expect(buildModifiedPlan.body).toMatch(/backfill `analysis`/);
        expect(buildModifiedPlan.body).toMatch(/still attach `analysis`/);
        expect(buildModifiedPlan.body).not.toMatch(/Omit `analysis`/);
        expect(presentDiff.body).toMatch(/Every node carries the `analysis` you set/);
        expect(presentDiff.body).not.toMatch(/set its `mockOnReplay`/);
    });
    it("build-trace-plan requires a replayable root before the tree is built", () => {
        const buildTracePlan = findStep("instrument", "build-trace-plan");
        // The check must fire BEFORE the tree is constructed, not after the plan is posted.
        expect(buildTracePlan.body).toMatch(/Replayability requirement/);
        expect(buildTracePlan.body).toMatch(/verify the root is replayable BEFORE you construct the tree/);
        // Both clearing cases are spelled out.
        expect(buildTracePlan.body).toMatch(/Serializable input/);
        expect(buildTracePlan.body).toMatch(/Replayable-root handler\/processor/);
        // A live-client argument does not satisfy it on its own.
        expect(buildTracePlan.body).toMatch(/single live-client argument does NOT satisfy it/);
        // If it clears neither, do not build or post the plan.
        expect(buildTracePlan.body).toMatch(/do not build or post the plan/);
        // The three resolutions route back through present-workflows.
        expect(buildTracePlan.body).toMatch(/Return to step \{\{step:instrument\/present-workflows\}\}/);
    });
    it("replay script instructions choose a safety-compatible mock strategy", () => {
        const writeInstrumentation = findStep("instrument", "write-instrumentation");
        expect(writeInstrumentation.body).toMatch(/mock: "marked"/);
        expect(writeInstrumentation.body).toMatch(/passes the safety-audited mock strategy/);
        expect(writeInstrumentation.body).toMatch(/synchronous TypeScript unsafe span/);
        expect(writeInstrumentation.body).toMatch(/trace_across_threads=True/);
        expect(writeInstrumentation.body).toMatch(/Ruby child-thread/);
        expect(writeInstrumentation.body).toMatch(/Do not hand-mock DB clients/);
        expect(writeInstrumentation.body).not.toMatch(/leave the DB unmocked/);
        expect(writeInstrumentation.body).not.toMatch(/reads today's data/);
    });
    it("classifies mockability from execution context as well as wrapper kind", () => {
        const buildTracePlan = findStep("instrument", "build-trace-plan");
        const buildModifiedPlan = findStep("modify", "build-modified-plan");
        for (const step of [buildTracePlan, buildModifiedPlan]) {
            expect(step.body).toMatch(/same replay context/);
            expect(step.body).toMatch(/trace_across_threads=True/);
            expect(step.body).toMatch(/pre-created consumers/);
            expect(step.body).toMatch(/TypeScript synchronous/);
            expect(step.body).toMatch(/mockable: false/);
        }
    });
    it("declares the `reference` appendix consulted by build-trace-plan and build-modified-plan", () => {
        expect(setupFlow.appendices.find((a) => a.id === "reference")).toBeDefined();
        const buildTracePlan = findStep("instrument", "build-trace-plan");
        const buildModifiedPlan = findStep("modify", "build-modified-plan");
        expect(buildTracePlan.kind).toBe("reference");
        expect(buildModifiedPlan.kind).toBe("reference");
        if (buildTracePlan.kind === "reference") {
            expect(buildTracePlan.refs).toEqual(["reference"]);
        }
        if (buildModifiedPlan.kind === "reference") {
            expect(buildModifiedPlan.refs).toEqual(["reference"]);
        }
    });
    it("every step is reachable in some (mode, target) combination", () => {
        const allStepIds = new Set();
        for (const phase of setupFlow.phases) {
            for (const step of phase.steps) {
                allStepIds.add(`${phase.id}/${step.id}`);
            }
        }
        const reachableUnion = new Set();
        for (const targetName of TARGET_NAMES) {
            for (const id of computeReachableSteps(setupFlow, targetName)) {
                reachableUnion.add(id);
            }
        }
        expect([...reachableUnion].sort()).toEqual([...allStepIds].sort());
    });
});
describe("renderMarkdown(setupFlow)", () => {
    it("renders without throwing for every target", () => {
        for (const targetName of TARGET_NAMES) {
            const target = TARGETS[targetName];
            expect(() => renderMarkdown(setupFlow, target)).not.toThrow();
        }
    });
    it("monolith section order follows the wizard chain, so a sequential reader cannot skip login", () => {
        // Cursor/Codex render one file and an agent reads it top to bottom. If a
        // wizard-reachable phase sits above Login and routes onward (Explain's
        // wizard exit goes to Approach), the wizard skips authentication entirely.
        for (const targetName of ["cursor", "codex"]) {
            const rendered = renderMarkdown(setupFlow, TARGETS[targetName]);
            const at = (heading) => rendered.indexOf(`\n## ${heading}`);
            for (const heading of ["Login", "Explain", "Approach", "Instrument"]) {
                expect(at(heading), `${targetName} is missing "## ${heading}"`).toBeGreaterThan(-1);
            }
            expect(at("Login"), `${targetName}: Login must precede Explain`).toBeLessThan(at("Explain"));
            expect(at("Explain"), `${targetName}: Explain must precede Approach`).toBeLessThan(at("Approach"));
            expect(at("Approach"), `${targetName}: Approach must precede Instrument`).toBeLessThan(at("Instrument"));
        }
    });
    it("the primitives explainer expands in every target's rendered output", () => {
        for (const targetName of TARGET_NAMES) {
            const rendered = renderMarkdown(setupFlow, TARGETS[targetName]);
            expect(rendered).not.toContain("{{primitivesExplainer}}");
            expect(rendered).toContain("**How to instrument**");
            expect(rendered).toContain("5. Skip execution and return modified outputs from the recorded trace");
            // The old CODE -> TRACES -> DATASETS -> IMPROVE diagram is gone: the
            // explainer replaced it in both the wizard intro and standalone explain.
            expect(rendered).not.toContain("│   CODE   │");
        }
    });
    it("codex output contains the BITFAB_PLUGIN_DIR resolution block; non-codex does not", () => {
        const codex = renderMarkdown(setupFlow, TARGETS.codex);
        expect(codex).toContain("BITFAB_PLUGIN_DIR=$(");
        expect(codex).toContain("CODEX_HOME");
        const claude = renderMarkdown(setupFlow, TARGETS.claude);
        expect(claude).not.toContain("CODEX_HOME");
        const cursor = renderMarkdown(setupFlow, TARGETS.cursor);
        expect(cursor).not.toContain("CODEX_HOME");
    });
    it("codex output uses 'ask the user' framing where claude/cursor use AskUserQuestion", () => {
        const codex = renderMarkdown(setupFlow, TARGETS.codex);
        const claude = renderMarkdown(setupFlow, TARGETS.claude);
        expect(claude).toContain("AskUserQuestion");
        expect(codex).not.toContain("Use `AskUserQuestion`");
        expect(codex).toContain("Ask the user");
    });
    it("routes a missing MCP tool to each target's own remedy, never a restart", () => {
        const claude = renderMarkdown(setupFlow, TARGETS.claude);
        expect(claude).toContain("run `/mcp`, enable **Bitfab**");
        expect(claude).toContain("Do **not** suggest restarting");
        for (const target of ["cursor", "codex"]) {
            const rendered = renderMarkdown(setupFlow, TARGETS[target]);
            expect(rendered).toContain("re-enable the Bitfab MCP server in their editor's MCP settings");
            expect(rendered).not.toContain("run `/mcp`");
            expect(rendered).not.toContain("claude mcp list");
        }
        for (const target of TARGET_NAMES) {
            expect(renderMarkdown(setupFlow, TARGETS[target])).toContain("Then **stop**, the same way a failed login stops.");
        }
    });
    it("apiKey MCP tool name reflects the target prefix", () => {
        expect(renderMarkdown(setupFlow, TARGETS.claude)).toContain("mcp__plugin_bitfab_Bitfab__get_bitfab_api_key");
        expect(renderMarkdown(setupFlow, TARGETS.cursor)).toContain("mcp__Bitfab__get_bitfab_api_key");
        expect(renderMarkdown(setupFlow, TARGETS.codex)).toContain("mcp__Bitfab__get_bitfab_api_key");
    });
    it("instrumentation replay guidance enforces root parity in every target", () => {
        for (const targetName of TARGET_NAMES) {
            const rendered = renderMarkdown(setupFlow, TARGETS[targetName]);
            expect(rendered).toContain("Replay root parity (hard rule)");
            expect(rendered).toContain("exact same exported top-level traced wrapper that production/runtime calls to create the root span");
            expect(rendered).toContain("You must do this unless it is genuinely impossible in the host app");
            expect(rendered).toContain("inconvenience, extra refactoring, an inline wrapper, or needing to move code is not impossible");
            expect(rendered).toContain("extract it into the nearest appropriate service/module, export it, and update both production and replay to import and call that same symbol");
            expect(rendered).toContain("Do not replay a convenient inner helper unless that exact helper is also the production root traced wrapper");
            expect(rendered).toContain("Avoid duplicate semantic wrappers split across production and replay with names like `runX`, `processX`, or `generateX`");
            expect(rendered).toContain("re-invokes the same framework entrypoint production calls");
            expect(rendered).not.toContain("re-invokes the framework entrypoint with the recorded root input plus");
            expect(rendered).not.toContain("the handler-recorded root stays replayable via a same-key wrapper in the replay script");
            expect(rendered).toContain("Replay root parity:");
            expect(rendered).toContain("- Production root symbol:");
            expect(rendered).toContain("- Production import/path:");
            expect(rendered).toContain("- Replay symbol:");
            expect(rendered).toContain("- Replay import/path:");
            expect(rendered).toContain("- Same symbol? yes/no");
            expect(rendered).toContain("- If no, why is this impossible?");
        }
    });
    it("standalone replay script creation also enforces root parity", () => {
        const step = findStep("replay", "create-scripts");
        expect(step.kind).toBe("action");
        if (step.kind !== "action") {
            throw new Error("unreachable");
        }
        expect(step.body).toContain("Replay root parity (hard rule)");
        expect(step.body).toContain("exact same exported top-level traced wrapper that production/runtime calls to create the root span");
        expect(step.body).toContain("You must do this unless it is genuinely impossible in the host app");
        expect(step.body).toContain("For handler-instrumented keys with explicit-key replay, verify parity against the production keyed handler/run-wrapper entrypoint");
        expect(step.body).toContain("Replay root parity verification");
        expect(step.body).toContain("Production root symbol:");
        expect(step.body).toContain("If no, why is this impossible?");
        expect(step.body).toContain("Every unsafe production action reached through that wiring must remain behind a replay-mockable marked span");
        expect(step.body).toContain("a genuinely replay-only callback slot with no production action and no recorded call to mock");
        expect(step.body).not.toContain("Substitute safe no-ops only for side-effectful wiring");
        expect(step.body).not.toContain("billing/credit callbacks, notification senders");
        const rendered = renderMarkdown(setupFlow, TARGETS.codex);
        expect(rendered).toContain("synthesize only genuinely replay-only slots with no production action and no recorded call to mock");
        expect(rendered).toContain("Every production billing, notification, write, or other unsafe callback must retain its real wiring behind a selected replay-mockable marked span");
        expect(rendered).not.toContain("billing/runtime callbacks");
        expect(rendered).not.toContain("write in a stub for every dependency");
    });
});
describe("split-chain dispatch integrity", () => {
    const STEP_BY_ID = new Map();
    for (const phase of setupFlow.phases) {
        for (const step of phase.steps) {
            STEP_BY_ID.set(`${phase.id}/${step.id}`, step);
        }
    }
    function entryStart(entry) {
        if (typeof entry === "string") {
            return entry;
        }
        const resolved = entry.claude ?? entry.default;
        if (resolved === undefined) {
            throw new Error("entry has no resolvable start step");
        }
        return resolved;
    }
    function walkChain(mode, start) {
        const visited = new Set();
        const terminals = new Set();
        const queue = [start];
        while (queue.length > 0) {
            const id = queue.shift();
            if (id === null || id === undefined || visited.has(id)) {
                continue;
            }
            visited.add(id);
            const step = STEP_BY_ID.get(id);
            if (step === undefined) {
                throw new Error(`mode "${mode}": Next ref "${id}" has no matching step`);
            }
            const refs = nextRefsForMode(step, mode);
            if (refs.every((ref) => ref === null)) {
                terminals.add(id);
            }
            for (const ref of refs) {
                queue.push(ref);
            }
        }
        return { visited, terminals };
    }
    it("every Next ref in every mode resolves to a real step or null", () => {
        const validIds = new Set(STEP_BY_ID.keys());
        for (const mode of Object.keys(setupFlow.entries)) {
            for (const [id, step] of STEP_BY_ID) {
                for (const ref of nextRefsForMode(step, mode)) {
                    if (ref !== null) {
                        expect(validIds.has(ref), `mode "${mode}" step "${id}" routes to missing step "${ref}"`).toBe(true);
                    }
                }
            }
        }
    });
    it("every mode's dispatch chain converges on cleanup/close-studio as its only terminal", () => {
        for (const [mode, entry] of Object.entries(setupFlow.entries)) {
            const { visited, terminals } = walkChain(mode, entryStart(entry));
            expect(visited.has("cleanup/close-studio"), `mode "${mode}" never reaches cleanup/close-studio`).toBe(true);
            expect([...terminals].sort(), `mode "${mode}" has unexpected terminal steps`).toEqual(["cleanup/close-studio"]);
        }
    });
    it("wizard chains login -> explain -> approach -> instrument -> cleanup", () => {
        const wizard = walkChain("wizard", entryStart(setupFlow.entries.wizard)).visited;
        for (const id of [
            "login/status-check",
            "explain/overview",
            "approach/choose-driver",
            "instrument/detect-language",
            "cleanup/close-studio",
        ]) {
            expect(wizard.has(id), `wizard chain missing "${id}"`).toBe(true);
        }
        const instrument = walkChain("instrument", entryStart(setupFlow.entries.instrument)).visited;
        expect(instrument.has("instrument/detect-language")).toBe(true);
        expect(wizard.has("replay/gather-keys")).toBe(false);
        expect(instrument.has("replay/gather-keys"), "instrument mode must NOT fall through into the replay phase").toBe(false);
    });
});
describe("rendered output hygiene", () => {
    const EXPECTED_FILE_COUNT = {
        claude: 15,
        cursor: 1,
        codex: 1,
    };
    it("renderFlow leaves no unresolved {{...}} template tokens in any file", () => {
        for (const targetName of TARGET_NAMES) {
            const files = renderFlow(setupFlow, TARGETS[targetName]);
            for (const file of files) {
                const leftover = file.content.match(/\{\{[^}]*\}\}/g);
                expect(leftover, `target "${targetName}" file "${file.slug || file.kind}" has unresolved tokens: ${leftover?.join(", ")}`).toBeNull();
            }
        }
    });
    it("compiles claude to an orchestrator + per-phase sub-skills, cursor/codex to a monolith", () => {
        for (const targetName of TARGET_NAMES) {
            const files = renderFlow(setupFlow, TARGETS[targetName]);
            expect(files.length, `target "${targetName}" produced an unexpected number of files`).toBe(EXPECTED_FILE_COUNT[targetName]);
        }
        const claudeKinds = renderFlow(setupFlow, TARGETS.claude).map((f) => f.kind);
        expect(claudeKinds.filter((kind) => kind === "orchestrator")).toHaveLength(1);
        expect(claudeKinds.filter((kind) => kind === "phase")).toHaveLength(14);
        expect(renderFlow(setupFlow, TARGETS.cursor)[0].kind).toBe("monolith");
        expect(renderFlow(setupFlow, TARGETS.codex)[0].kind).toBe("monolith");
    });
});
